import React, { useState, useEffect } from "react";
// 1. Import 'Link' and 'useNavigate' correctly from 'react-router-dom'.
import { Link, useNavigate } from "react-router-dom";
import { adminLogin, login } from "../redux/actions/authAction";
import { useDispatch, useSelector } from "react-redux";

const Login = () => {
    const initialState = { email: "", password: "" };
    const [userData, setUserData] = useState(initialState);
    const [userType, setUserType] = useState(false);
    const { email, password } = userData;

    const [typePass, setTypePass] = useState(false);

    const { auth } = useSelector((state) => state);

    const dispatch = useDispatch();
    const navigate = useNavigate();

    useEffect(() => {
        // 2. Use the 'navigate' function instead of 'history.push'
        if (auth.token) navigate("/");
    // 3. Add 'navigate' to the dependency array instead of 'history'
    }, [auth.token, navigate]);

    const handleChangeInput = (e) => {
        const { name, value } = e.target;
        setUserData({ ...userData, [name]: value });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!userType) {
            dispatch(login(userData));
        } else {
            dispatch(adminLogin(userData));
        }
    };

    return (
        <div className="auth_page">
            <form onSubmit={handleSubmit} className="inner-shadow">
                <h3 className="text-uppercase text-center mb-4 auth-heading ">
                    Campus Connect
                </h3>
                <div className="mb-3">
                    <label htmlFor="exampleInputEmail1" className="form-label">
                        Email address
                    </label>
                    <div className="outer-shadow hover-in-shadow form-input-wrap">
                        <input
                            type="email"
                            className="form-control "
                            id="exampleInputEmail1"
                            aria-describedby="emailHelp"
                            onChange={handleChangeInput}
                            value={email}
                            name="email"
                        />
                    </div>
                    <div id="emailHelp" className="form-text">
                        We'll never share your email with anyone else.
                    </div>
                </div>
                <div className="mb-3">
                    <label htmlFor="exampleInputPassword1" className="form-label">
                        Password
                    </label>
                    <div className="pass">
                        <div className="outer-shadow hover-in-shadow form-input-wrap">
                            <input
                                type={typePass ? "text" : "password"}
                                className="form-control"
                                id="exampleInputPassword1"
                                onChange={handleChangeInput}
                                value={password}
                                name="password"
                            />
                            <small onClick={() => setTypePass(!typePass)}>
                                {typePass ? "Hide" : "Show"}
                            </small>
                        </div>
                    </div>
                </div>

                <div className="d-flex justify-content-evenly  mx-0 mb-4">
                    <label htmlFor="User">
                        User:
                        <input
                            type="radio"
                            id="User"
                            name="gender"
                            value={userType}
                            defaultChecked
                            onClick={() => setUserType(false)}
                        />
                    </label>

                    <label htmlFor="Admin">
                        Admin:
                        <input
                            type="radio"
                            id="Admin"
                            name="gender"
                            value={userType}
                            onClick={() => setUserType(true)}
                        />
                    </label>
                </div>

                <button
                    type="submit"
                    className="btn-1 w-100 d-flex outer-shadow hover-in-shadow justify-content-center"
                    disabled={email && password ? false : true}
                >
                    Login
                </button>
                <p className="my-2">
                    Don't have an account?{" "}
                    <Link to="/register" style={{ color: "crimson" }}>
                        Register Now.
                    </Link>
                </p>
            </form>
        </div>
    );
};

export default Login;
